"""Golden diary fixtures (Plan 11 Task 5): packages/test-fixtures/diary.

The expected files are generated by scripts/generate_diary_expectations.py from the real
aggregation. The numbers asserted below are worked by hand from the inputs, so a generator bug
cannot bless a wrong number (and a wrong "unknown counted as 0" shows up here)."""

import json
import subprocess
import sys
from pathlib import Path

from tests.fixtures.loader import FIXTURES

DIARY = FIXTURES / "diary"
INPUTS = DIARY / "inputs"
EXPECTED = DIARY / "expected"
API_DIR = Path(__file__).resolve().parents[2]


def _expected(stem: str) -> dict:
    return json.loads((EXPECTED / f"{stem}.json").read_text(encoding="utf-8"))


def test_expectations_are_current():
    """CI fails if stale: `uv run python scripts/generate_diary_expectations.py --write`,
    then review with nutrition-safety-reviewer; never edit an expected file by hand."""
    done = subprocess.run(
        [sys.executable, "scripts/generate_diary_expectations.py", "--check"],
        cwd=API_DIR,
        capture_output=True,
        text=True,
        check=False,
    )
    assert done.returncode == 0, done.stdout + done.stderr


def test_every_input_has_expected():
    inputs = {p.name for p in INPUTS.glob("*.json")}
    assert inputs == {p.name for p in EXPECTED.glob("*.json")}
    assert {n.removesuffix(".json") for n in inputs} == {
        "day_complete_under",
        "day_over_energy",
        "day_incomplete_energy",
        "day_quick_add_kcal_only",
        "day_empty",
        "day_no_target",
        "day_consent_required",
        "day_paused_pregnancy",
        "day_hide_energy",
        "day_hide_all",
        "day_half_up",
        "day_archived_slot",
        "week_mixed",
        "week_hide_all",
    }


def test_hand_checked_goldens():
    # G1 guide: 2760 kcal, protein 112, fat 77, carbs 405 (spec 4.12).
    over = _expected("day_over_energy")
    assert over["remaining"]["energy_kcal"] == -250.4  # 2760 - (1200.4 + 1000 + 810)
    assert over["remaining"]["protein_g"] == -8.0 and over["progress"]["energy_kcal"] == 1.09

    half = _expected("day_half_up")
    assert half["remaining"]["protein_g"] == 61.8  # 112 - 50.25 = 61.75, half up

    empty = _expected("day_empty")
    assert empty["remaining"] == {
        "energy_kcal": 2760.0,
        "protein_g": 112.0,
        "fat_g": 77.0,
        "carbs_g": 405.0,
    }
    assert all(v == 0.0 for v in empty["progress"].values())
    assert all(v is None for v in empty["totals"].values())  # nothing logged is null, not 0

    quick = _expected("day_quick_add_kcal_only")
    assert quick["remaining"]["energy_kcal"] == 2310.0  # 2760 - 450
    assert [quick["remaining"][k] for k in ("protein_g", "fat_g", "carbs_g")] == [None] * 3
    assert quick["limits_bands"]["sugar_g"] == "unknown"
    assert quick["limits_bands"]["salt_g"] == "unknown"

    under = _expected("day_complete_under")
    assert under["totals"]["energy_kcal"] == 1501.3  # 228 + 640.5 + 112.5 + 520.25 = 1501.25
    assert under["remaining"]["energy_kcal"] == 1258.8  # 2760 - 1501.25 = 1258.75
    assert under["remaining"]["protein_g"] == 67.4  # 112 - 44.65 = 67.35
    assert under["progress"]["energy_kcal"] == 0.54 and under["progress"]["protein_g"] == 0.4
    assert not any(under["incomplete"].values())


def test_unknown_is_never_counted_as_zero():
    inc = _expected("day_incomplete_energy")
    assert inc["incomplete"]["energy_kcal"] is True
    assert inc["totals"]["energy_kcal"] == 300.0  # a lower bound: the OFF entry has no energy
    assert inc["remaining"]["energy_kcal"] is None and inc["progress"]["energy_kcal"] is None
    assert inc["remaining"]["protein_g"] == 89.5  # 112 - (10 + 12.5): protein is known


def test_no_target_states():
    for stem, status in (
        ("day_no_target", "none"),
        ("day_paused_pregnancy", "paused_pregnancy"),
        ("day_consent_required", "consent_required"),
    ):
        d = _expected(stem)
        assert d["targets_status"] == status
        assert d["remaining"] is None and d["progress"] is None, stem
    assert _expected("day_consent_required")["targets"] is None


def test_archived_slot_rule():
    d = _expected("day_archived_slot")
    shown = [(s["custom_label"] or s["label_key"], s["archived"]) for s in d["slots"]]
    assert ("Pre-gym", True) in shown  # an archived slot with an entry is listed
    assert all(label != "Never used" for label, _ in shown)  # one without entries is not


def test_week_mixed_hand_checked():
    w = _expected("week_mixed")
    assert w["days"][0]["date"] == "2026-11-01" and len(w["days"]) == 7
    # Averaged days: 1, 2, 5, 6 and 7 Nov (3 Nov is marked partial, 4 Nov is empty).
    assert w["averaged_days"] == 5
    assert w["averages"]["energy_kcal"] == 1630.0  # (2000 + 1500 + 2400 + 1800 + 450) / 5
    assert w["averages"]["protein_g"] == 91.0  # (120 + 75 + 60 + 200) / 5, a lower bound
    assert w["averages_incomplete"]["energy_kcal"] is True  # 5 Nov has an entry without energy
    assert w["averages_incomplete"]["protein_g"] is True  # the quick add has no protein
    assert w["protein_met_days"] == 2  # 1 Nov (120 >= 112) and 2 Nov (75 >= its own 71)
    days = {t["date"]: t for t in w["days"]}
    assert days["2026-11-02"]["targets"] == {"energy_kcal": 1540, "protein_g": 71}  # frozen G2
    assert days["2026-11-01"]["targets"] == {"energy_kcal": 2760, "protein_g": 112}  # frozen G1
    assert days["2026-11-06"]["targets"] is None and days["2026-11-06"]["progress"] is None
    assert days["2026-11-03"]["partial_logged"] is True and days["2026-11-04"]["items"] == 0
    assert days["2026-11-04"]["totals"]["energy_kcal"] is None
    assert days["2026-11-05"]["progress"]["energy_kcal"] is None  # energy incomplete


def _numbers(node, path=""):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from _numbers(v, f"{path}.{k}")
    elif isinstance(node, list):
        for i, v in enumerate(node):
            yield from _numbers(v, f"{path}[{i}]")
    elif isinstance(node, (int, float)) and not isinstance(node, bool):
        yield path, node


def test_hidden_numbers_leave_no_digit_for_energy_or_macros():
    nutrient = {
        "energy_kcal",
        "protein_g",
        "fat_g",
        "carbs_g",
        "fibre_g",
        "sugars_g",
        "salt_g",
        "sat_fat_g",
    }
    # hide_energy: every energy number is null, wherever it appears.
    day = _expected("day_hide_energy")
    week = _expected("week_hide_all")
    for doc in (day,):
        for path, _ in _numbers(doc):
            leaf = path.rsplit(".", 1)[-1]
            if ".progress" in path:
                continue  # the ring shape (0.25 steps) stays
            assert "energy" not in leaf and "kcal" not in leaf, path
    # hide_all: every nutrient number is null; portions, positions and progress stay.
    for doc in (_expected("day_hide_all"), week):
        for path, value in _numbers(doc):
            leaf = path.rsplit(".", 1)[-1]
            if leaf in nutrient and ".progress" not in path:
                raise AssertionError(f"{path} = {value}")
    progress = _expected("day_hide_all")["progress"]
    assert all(v in (0.0, 0.25, 0.5, 0.75, 1.0) for v in progress.values() if v is not None)
    assert _expected("day_hide_all")["slots"][0]["entries"][0]["grams"] == 60.0
